"""Original queue, catalogue and download integration for observed HUC changes."""
from model import observed_landcover, observed_landcover_handover

ACTIONS = {"observed.landcover.import", "observed.landcover.save", "observed.landcover.handover"}


def _downloads(operator, workspace_key, edition):
    workspace = operator.ws(workspace_key)
    from model.common import verify_file
    return [operator._ticket(workspace_key, verify_file(workspace.root, row), row, name)
            for name, row in edition["files"].items() if not name.startswith("originals/")]


def _handover_downloads(operator, workspace_key, value):
    workspace = operator.ws(workspace_key)
    from model.common import relative_file
    labels = {
        "Recipient_Package.zip": "Complete recipient package ZIP — extract and open START_HERE.html",
        "Report/Watershed_Scientific_Report.pdf": "Original scientific PDF",
        "Report/Watershed_Offline_Reader.html": "Standalone offline report and original sources",
        "Editable_Study.zip": "Original editable Study ZIP",
        "Report/Original_Saved_Report.zip": "Original saved scientific edition ZIP",
        "Comparison/selected-huc-landcover.zip": "Original comparison ZIP",
        "Package_Manifest.json": "Complete package inventory",
    }
    # Catalogues read immutable metadata only; the file transport reopens the
    # original retained bytes. Full inspect/build validates the complete package.
    return [{**operator._ticket(workspace_key, relative_file(workspace.root, value["files"][name]["path"]),
                                value["files"][name], label), "member": name}
            for name, label in labels.items()]


def _investigation_snapshot(operator, workspace_key):
    provider = getattr(operator.extensions, "_extensions", {}).get("study-transfer", {}).get("provider")
    method = getattr(provider, "_investigation_snapshot", None)
    if not callable(method):
        raise ValueError("Install the original Study transfer provider before preparing a recipient package")
    return method(workspace_key)


def invoke(operator, workspace_key, action, payload):
    workspace = operator.ws(workspace_key)
    if action == "observed.landcover.import":
        if payload:
            raise ValueError("Import the installed original completed land-cover source manifest")
        return observed_landcover.import_published(workspace)
    if action == "observed.landcover.save":
        return observed_landcover.build(workspace, payload)
    if action == "observed.landcover.handover":
        if set(payload) != {"comparison_id", "report_id"}:
            raise ValueError("Choose the saved comparison and its exact completed scientific report")
        snapshot = _investigation_snapshot(operator, workspace_key)
        return observed_landcover_handover.build(
            workspace, payload["comparison_id"], payload["report_id"],
            investigation_snapshot=snapshot)
    raise ValueError("Select an original observed land-cover action")


def read(operator, workspace_key, operation, payload):
    workspace = operator.ws(workspace_key)
    if operation == "catalog":
        return observed_landcover.catalog(workspace)
    if operation == "inputs":
        return observed_landcover.preview(workspace, payload["selection"])
    if operation == "edition":
        result = observed_landcover.inspect(workspace, payload["id"])
        result["_downloads"] = _downloads(operator, workspace_key, result["edition"])
        return result
    if operation == "handover-catalog":
        value = observed_landcover_handover.catalog(workspace, payload["id"])
        for row in value["handovers"]:
            row["_downloads"] = _handover_downloads(operator, workspace_key, row)
            row.pop("files", None)
        return value
    if operation == "handover":
        value = observed_landcover_handover.inspect(workspace, payload["id"])
        value["_downloads"] = _handover_downloads(operator, workspace_key, value)
        return value
    raise ValueError("Select an original observed land-cover reader")


def overview(operator, workspace_key):
    return observed_landcover.overview(operator.ws(workspace_key))


def decorate_task(operator, task):
    if task["action"] == "observed.landcover.save" and task["state"] == "complete":
        value = observed_landcover.inspect(operator.ws(task["workspace"]), task["result"]["id"])
        task["_downloads"] = _downloads(operator, task["workspace"], value["edition"])
        task["_item"] = {"kind": observed_landcover.KIND, "id": value["edition"]["id"]}
    if task["action"] == "observed.landcover.handover" and task["state"] == "complete":
        value, _ = observed_landcover_handover._record(operator.ws(task["workspace"]), task["result"]["id"])
        task["_downloads"] = _handover_downloads(operator, task["workspace"], value)
        task["_item"] = {"kind": observed_landcover_handover.KIND, "id": value["id"]}
    return task

/** Readable native views over the exact completed paired-class matrices. */
const GROUPS = [
  ['water','Water',[11]],['snow_ice','Snow / ice',[12]],
  ['developed','Developed',[21,22,23,24]],['barren','Barren',[31]],
  ['forest','Forest',[41,42,43]],['shrub','Shrub',[52]],
  ['grass','Grass',[71]],['agriculture','Agriculture',[81,82]],
  ['wetland','Wetland',[90,95]]
];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>value===null?'Not available':Number(value).toLocaleString(undefined,{maximumFractionDigits:3});
const pct=(n,d)=>d?100*n/d:null;
const requireValue=(condition,message)=>{if(!condition)throw Error(message);};

export function originalLandcoverGroups(view,cellAreaM2){
  requireValue(Number.isFinite(cellAreaM2)&&cellAreaM2>0,'The original native cell area is unavailable.');
  requireValue(Number.isSafeInteger(view?.paired_valid_cells)&&view.paired_valid_cells>=0,
    'The original paired support is unavailable.');
  const groups=GROUPS.map(([id,label,codes])=>({id,label,codes:[...codes],before_cells:0,after_cells:0,
    retained_within_group_cells:0,internal_class_change_cells:0,gross_loss_cells:0,gross_gain_cells:0}));
  const byClass=new Map(groups.flatMap(group=>group.codes.map(code=>[code,group])));
  const seen=new Set();let paired=0,changed=0,changedGroup=0;
  requireValue(Array.isArray(view.transitions),'The complete original directional matrix is unavailable.');
  for(const row of view.transitions){
    const before=byClass.get(row.before_class),after=byClass.get(row.after_class),key=row.before_class+'|'+row.after_class;
    requireValue(before&&after&&!seen.has(key)&&Number.isSafeInteger(row.cells)&&row.cells>=0,
      'The original directional matrix has an invalid or repeated class pair.');
    const expected=row.cells*cellAreaM2/10000;
    requireValue(Number.isFinite(row.area_ha)&&Math.abs(row.area_ha-expected)<=Math.max(1e-9,Math.abs(expected)*1e-10),
      'A directional area differs from its original native cell support.');
    seen.add(key);paired+=row.cells;before.before_cells+=row.cells;after.after_cells+=row.cells;
    if(row.before_class!==row.after_class)changed+=row.cells;
    if(before===after){
      before.retained_within_group_cells+=row.cells;
      if(row.before_class!==row.after_class)before.internal_class_change_cells+=row.cells;
    }else{before.gross_loss_cells+=row.cells;after.gross_gain_cells+=row.cells;changedGroup+=row.cells;}
  }
  requireValue(seen.size===byClass.size**2&&paired===view.paired_valid_cells&&changed===view.changed_class_cells,
    'The full matrix differs from the original retained support.');
  const area=cells=>cells*cellAreaM2/10000;
  return {paired_valid_cells:paired,changed_class_cells:changed,changed_group_cells:changedGroup,
    within_group_class_change_cells:changed-changedGroup,rows:groups.map(group=>{
      const net=group.after_cells-group.before_cells;
      return {...group,net_cells:net,gross_turnover_cells:group.gross_gain_cells+group.gross_loss_cells,
        before_area_ha:area(group.before_cells),after_area_ha:area(group.after_cells),
        gross_gain_area_ha:area(group.gross_gain_cells),gross_loss_area_ha:area(group.gross_loss_cells),
        net_area_ha:area(net),retained_area_ha:area(group.retained_within_group_cells),
        internal_class_change_area_ha:area(group.internal_class_change_cells),
        loss_percent_of_before_group:pct(group.gross_loss_cells,group.before_cells),
        gain_percent_of_after_group:pct(group.gross_gain_cells,group.after_cells),
        net_percent_of_paired_valid:pct(net,paired)};
    })};
}

function groupChart(groups,label){
  const maximum=Math.max(...groups.rows.flatMap(row=>[row.gross_loss_area_ha,row.gross_gain_area_ha,Math.abs(row.net_area_ha)]));
  const extent=maximum||1,origin=460,half=245,scale=value=>half*value/extent;
  const ticks=maximum?[-1,-.5,0,.5,1]:[0];
  const grid=ticks.map(value=>{
    const x=origin+half*value;
    return '<line x1="'+x+'" y1="45" x2="'+x+'" y2="383" stroke="'+(value===0?'#333':'#d8d8d8')+'"/>'+
      '<text x="'+x+'" y="405" text-anchor="middle">'+esc(number(value*maximum))+'</text>';
  }).join('');
  const marks=groups.rows.map((row,index)=>{
    const y=68+index*37,gain=scale(row.gross_gain_area_ha),loss=scale(row.gross_loss_area_ha),net=origin+scale(row.net_area_ha);
    return '<g><title>'+esc(row.label+': gained '+number(row.gross_gain_area_ha)+' ha; lost '+number(row.gross_loss_area_ha)+
      ' ha; net '+number(row.net_area_ha)+' ha')+'</title><text x="12" y="'+(y+4)+'">'+esc(row.label)+'</text>'+
      '<rect x="'+(origin-loss)+'" y="'+(y-10)+'" width="'+loss+'" height="12" fill="#ddd" stroke="#555"/>'+
      '<rect x="'+origin+'" y="'+(y-10)+'" width="'+gain+'" height="12" fill="#555"/>'+
      '<path d="M '+net+' '+(y+6)+' l 5 5 l -5 5 l -5 -5 Z" fill="#111"/></g>';
  }).join('');
  return '<div class="olc-scroll olc-group-chart" tabindex="0" role="region" aria-label="Land-cover group chart, scroll horizontally">'+
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 445" width="760" height="445" role="img" aria-label="'+
    esc(label+'; gross group losses left, gains right, net change diamonds. Complete values in the following table.')+'">'+
    '<rect width="760" height="445" fill="#fff"/><g font-family="Arial,sans-serif" font-size="14" fill="#222">'+
    '<text x="215" y="25">Gross loss ←</text><text x="705" y="25" text-anchor="end">→ Gross gain</text>'+grid+marks+
    '<text x="460" y="435" text-anchor="middle">Hectares · diamond = net change (gain − loss)</text></g></svg></div>';
}

export function renderOriginalLandcoverGroups(view,cellAreaM2,{label='Original selected watershed group changes',before,after}={}){
  const groups=originalLandcoverGroups(view,cellAreaM2);
  const columns=['Land-cover group',String(before)+' paired ha',String(after)+' paired ha','Gross gain ha','Gross loss ha',
    'Net change ha','Loss / earlier group %','Gain / later group %','Within-group class-change ha'];
  const fields=['before_area_ha','after_area_ha','gross_gain_area_ha','gross_loss_area_ha','net_area_ha',
    'loss_percent_of_before_group','gain_percent_of_after_group','internal_class_change_area_ha'];
  const table='<div class="olc-scroll" tabindex="0" role="region" aria-label="Complete original land-cover group values, scroll horizontally">'+
    '<table><caption>Original paired support: '+esc(number(groups.paired_valid_cells))+' cells</caption><thead><tr>'+
    columns.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+
    groups.rows.map(row=>'<tr><th scope="row">'+esc(row.label)+'<small class="olc-group-codes">'+esc(row.codes.join(', '))+'</small></th>'+
      fields.map(field=>'<td title="'+esc(row[field]===null?'Not available':row[field])+'">'+esc(number(row[field]))+'</td>').join('')+
      '</tr>').join('')+'</tbody></table></div>';
  return '<section class="olc-group-summary"><h3>Land-cover groups · gross gains, losses and net change</h3>'+
    '<p>Gross gain and loss count cells crossing a group boundary. A switch between two forest classes remains within forest; developed classes follow the same rule. All nine groups use the same hectare scale for this reporting area.</p>'+
    '<p>'+esc(number(groups.changed_group_cells))+' cells changed group; '+esc(number(groups.within_group_class_change_cells))+
    ' more changed class within their group. Together they equal the original '+esc(number(groups.changed_class_cells))+' changed-class cells.</p>'+
    groupChart(groups,label)+table+'<p class="olc-note">Loss percentages use the earlier group; gain percentages use the later group. A zero group denominator is Not available. These summaries use the original paired-valid support. Independent annual inventories and each directional class change follow below.</p></section>';
}

/** Recipient packages for an exact saved watershed comparison and completed report. */
const list=value=>Array.isArray(value)?value:[];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validId=value=>typeof value==='string'&&/^[0-9a-f]{64}$/.test(value);
const terminal=state=>['complete','failed','interrupted','cancelled','canceled'].includes(state);
const action='observed.landcover.handover';
const short=value=>String(value??'').slice(0,12);
const storageKey=(workspace,id)=>'upstate.landcover-handover/v1:'+workspace+':'+id;

export function createObservedLandcoverHandover(host){
  const {getState,api,endpoint,openForm,submitAction}=host;
  let root=null,workspace='',comparisonId='',generation=0,readTicket=0,detailTicket=0,events=null;
  const contexts=new Map();
  const selectedWorkspace=()=>getState()?.workspace_key||'';
  function context(w,id){
    const key=w+':'+id;
    if(!contexts.has(key)){
      const value={reportId:'',selectionRevision:0,catalog:null,tasks:new Map(),submitting:false,checking:false,message:'',error:false};
      try{
        const saved=JSON.parse(globalThis.sessionStorage?.getItem(storageKey(w,id))||'null');
        if(validId(saved?.reportId))value.reportId=saved.reportId;
        for(const row of list(saved?.tasks)){
          if(validId(row.id)&&validId(row.reportId))value.tasks.set(row.id,{reportId:row.reportId,state:'unknown'});
        }
      }catch{}
      contexts.set(key,value);
    }
    return contexts.get(key);
  }
  function persist(w,id,c){
    try{globalThis.sessionStorage?.setItem(storageKey(w,id),JSON.stringify({
      reportId:c.reportId,tasks:[...c.tasks].map(([taskId,row])=>({id:taskId,reportId:row.reportId})),
    }));}catch{}
  }
  const current=(w,id,g)=>!!root&&workspace===w&&comparisonId===id&&generation===g&&selectedWorkspace()===w;
  const find=selector=>root?.querySelector(selector);
  function note(c,message,error=false){
    c.message=String(message||'');c.error=error;
    const node=find('[data-lch-note]');
    if(node){node.textContent=c.message;node.setAttribute('role',error?'alert':'status');}
  }
  function tickets(items){
    return list(items).map(row=>{
      if(typeof row.url!=='string'||!/^\/api\/file\/[0-9a-f]{64}$/.test(row.url))
        throw Error('Reopen this retained package to obtain its original authenticated downloads.');
      return '<a href="'+esc(row.url)+'?download=1">'+esc(row.label||row.filename||'Original file')+'</a>';
    }).join('');
  }
  function validateCatalog(value,id){
    if(value?.comparison?.id!==id||!Array.isArray(value.reports)||!Array.isArray(value.handovers))
      throw Error('The recipient catalog does not belong to this saved comparison.');
    const ids=new Set();
    for(const row of value.reports){
      if(!validId(row.id)||ids.has(row.id))throw Error('The completed report catalog repeats or loses an original identity.');
      ids.add(row.id);
    }
    for(const row of value.handovers){
      if(!validId(row.id)||row.comparison_id!==id||row.state!=='complete'||!validId(row.report_id))
        throw Error('The recipient package has another saved comparison identity.');
      tickets(row._downloads);
    }
    return value;
  }
  function render(c){
    if(!root)return;
    const catalog=c.catalog,reports=list(catalog?.reports),handovers=list(catalog?.handovers);
    const active=[...c.tasks].filter(([,row])=>!terminal(row.state));
    const chosen=reports.find(row=>row.id===c.reportId);
    const pending=c.submitting||active.some(([,row])=>row.reportId===c.reportId);
    root.innerHTML='<section class="olc-panel" aria-label="Recipient handover">'+
      '<h3>Recipient package</h3><p>Send this saved comparison with an existing scientific report, its original sources and an editable Study.</p>'+
      '<div data-lch-note role="status" aria-live="polite"></div>'+
      (!catalog?'<p>Reading matching completed reports and retained packages…</p>':
        reports.length?'<div class="olc-toolbar"><label>Completed scientific report<select data-lch-report>'+
          '<option value="">Choose a completed report</option>'+
          (c.reportId&&!chosen?'<option value="'+esc(c.reportId)+'" selected disabled>Previously selected report is unavailable</option>':'')+
          reports.map(row=>'<option value="'+esc(row.id)+'"'+(row.id===c.reportId?' selected':'')+'>'+
            esc(row.title||'Saved scientific report')+' · '+esc(short(row.id))+'</option>').join('')+
          '</select></label><button type="button" data-lch-create'+(!chosen||pending?' disabled':'')+'>Create recipient package</button></div>':
        '<p>No completed scientific report contains this exact saved comparison yet. Use the existing report controls above to compose and save its Scientific Report, then refresh this panel.</p>')+
      '<div class="olc-toolbar"><button type="button" data-lch-refresh>Refresh reports and packages</button></div>'+
      (active.length?'<p>'+esc(active.length)+' accepted package operation'+(active.length===1?' is':'s are')+
        ' retained in Tasks. You may leave this comparison; returning will read the original task.</p>':'')+
      (c.tasks.size?'<details><summary>Original package tasks</summary><ul>'+[...c.tasks].map(([taskId,row])=>
        '<li>Task <code title="'+esc(taskId)+'">'+esc(short(taskId))+'</code> · report '+esc(short(row.reportId))+
        ' · '+esc(row.state)+'. Continue the original task in Tasks.</li>').join('')+'</ul></details>':'')+
      '<div data-lch-detail></div>'+
      '<h4>Retained recipient packages</h4>'+
      (handovers.length?'<ul>'+handovers.map(row=>'<li><strong>'+esc(row.title||'Recipient package')+'</strong>'+
        ' · report '+esc(short(row.report_id))+' <button type="button" data-lch-open="'+esc(row.id)+'">Open package downloads</button>'+
        '<div class="olc-downloads">'+tickets(row._downloads)+'</div></li>').join('')+'</ul>':
        '<p>No recipient package has been retained for this comparison.</p>')+
      '<p>The package uses completed report files. It does not run a model or render a replacement report. Download and extract the complete bundle, then open START_HERE for its reader, files and editable reopening instructions.</p></section>';
    note(c,c.message,c.error);
  }
  async function refresh(){
    if(!root)return false;
    const w=workspace,id=comparisonId,g=generation,ticket=++readTicket,c=context(w,id),prior=c.reportId,selectionRevision=c.selectionRevision;
    note(c,'Reading exact matching completed reports…');
    try{
      const value=validateCatalog(await api(endpoint('/api/observed-landcover/handover-catalog',{workspace:w,id})),id);
      if(!current(w,id,g)||ticket!==readTicket)return false;
      c.catalog=value;
      // Preserve any explicit selector edit made while the catalog was read.
      if(!c.reportId&&c.reportId===prior&&c.selectionRevision===selectionRevision&&value.reports.length)c.reportId=value.reports[0].id;
      persist(w,id,c);
      note(c,value.reports.length?'Choose a completed report, or open a retained package below.':
        'Save a Scientific Report containing this comparison, then refresh.');
      render(c);
      return true;
    }catch(error){
      if(current(w,id,g)&&ticket===readTicket){note(c,error.message||String(error),true);render(c);}
      return false;
    }
  }
  async function openPackage(id){
    if(!root||!validId(id))return;
    const w=workspace,comparison=comparisonId,g=generation,ticket=++detailTicket,c=context(w,comparison);
    note(c,'Verifying the retained package and reading its original downloads…');
    try{
      const value=await api(endpoint('/api/observed-landcover/handover',{workspace:w,id}));
      if(!current(w,comparison,g)||ticket!==detailTicket)return;
      if(value?.id!==id||value.state!=='complete'||value.comparison_id!==comparison||!validId(value.report_id))
        throw Error('The retained package belongs to another saved comparison.');
      const links=tickets(value._downloads);
      const target=find('[data-lch-detail]');
      if(target)target.innerHTML='<section class="olc-panel"><h4>'+esc(value.title||'Recipient package')+
        '</h4><p>Saved comparison '+esc(short(comparison))+' · completed report '+esc(short(value.report_id))+
        '.</p><div class="olc-downloads">'+links+'</div>'+
        '<p>Start with the complete recipient bundle. Extract it before opening START_HERE; the editable Study ZIP retains its original project and source records.</p></section>';
      note(c,'Retained package verified. The links save its original files.');
    }catch(error){if(current(w,comparison,g)&&ticket===detailTicket)note(c,error.message||String(error),true);}
  }
  function matchesTask(task,w,id,reportId){
    return task?.workspace===w&&task.action===action&&task.payload?.comparison_id===id&&task.payload?.report_id===reportId;
  }
  function retainTask(c,w,id,reportId,task){
    if(!validId(task?.id))throw Error('The original queue did not return an accepted task identifier.');
    if(task.workspace!==undefined&&task.workspace!==w)throw Error('The accepted task belongs to another Workspace.');
    if(task.action!==undefined&&task.action!==action)throw Error('The accepted task has another action.');
    if(task.payload!==undefined&&(task.payload.comparison_id!==id||task.payload.report_id!==reportId))
      throw Error('The accepted task changed its comparison or report selection.');
    c.tasks.set(task.id,{reportId,state:'accepted'});persist(w,id,c);
  }
  function create(){
    if(!root)return;
    const w=workspace,id=comparisonId,g=generation,c=context(w,id);
    const report=list(c.catalog?.reports).find(row=>row.id===c.reportId);
    if(!report)throw Error('Choose a completed Scientific Report containing this exact comparison.');
    if(c.submitting||[...c.tasks.values()].some(row=>row.reportId===report.id&&!terminal(row.state)))
      throw Error('Continue the existing accepted package task, or refresh its status.');
    const payload={comparison_id:id,report_id:report.id};
    openForm('Create recipient package',
      'Collect the saved comparison, completed scientific report, original sources and editable Study.',
      '<p><strong>'+esc(c.catalog.comparison.title)+'</strong></p>'+
      '<p>'+esc(list(c.catalog.comparison.huc12s).length)+' original selected watersheds. Completed report: <strong>'+
      esc(report.title||'Saved scientific report')+'</strong>.</p>'+
      '<p>The package includes START_HERE, the offline reader and PDF, complete source downloads and the editable Study ZIP. Existing completed reports and original sources stay unchanged.</p>'+
      '<details><summary>Exact saved selection</summary><pre>'+esc(JSON.stringify(payload,null,2))+'</pre></details>',
      'Create complete recipient package',async()=>{
        if(!current(w,id,g)||c.reportId!==report.id)
          throw Error('Reopen the recipient package form for the current Workspace, comparison and report.');
        if(c.submitting)throw Error('This package request is already being submitted.');
        c.submitting=true;render(c);note(c,'Submitting this exact saved comparison and report to the original task queue…');
        try{
          const result=await submitAction(action,{...payload});
          // An accepted operation remains owned by its original context even
          // when the user leaves while the POST response is in flight.
          retainTask(c,w,id,report.id,result);
          if(current(w,id,g))note(c,'Package task accepted. Follow its original task or return here for completed downloads.');
          return result;
        }finally{
          c.submitting=false;
          if(current(w,id,g))render(c);
        }
      });
  }
  async function update(){
    if(!root)return;
    const w=workspace,id=comparisonId,g=generation,c=context(w,id);
    if(selectedWorkspace()!==w){detach();return;}
    if(c.checking)return;
    const pending=[...c.tasks].filter(([,row])=>!terminal(row.state));
    if(!pending.length)return;
    c.checking=true;
    let completed=false,changed=false;
    try{
      for(const [taskId,tracked] of pending){
        if(!current(w,id,g))break;
        let task=list(getState()?.tasks).find(row=>row.id===taskId&&row.workspace===w);
        // Use the original detail endpoint when state does not carry this task.
        if(!task||terminal(task.state)||!task.payload)task=await api(endpoint('/api/task',{id:taskId}));
        if(!current(w,id,g))break;
        if(!matchesTask(task,w,id,tracked.reportId))
          throw Error('The retained task no longer matches its original comparison and report.');
        const old=tracked.state;
        if(task.state==='complete'){
          if(!validId(task.result?.id)||task.result.comparison_id!==id||task.result.report_id!==tracked.reportId)
            throw Error('The completed package task returned another saved selection.');
          tracked.handoverId=task.result.id;completed=true;
        }else if(terminal(task.state)){
          note(c,'The original package task '+short(taskId)+' is '+task.state+
            '. Open it in Tasks to inspect the actual error and resume the same operation.',true);
        }
        tracked.state=task.state;changed=changed||old!==task.state;
      }
      if(current(w,id,g)){
        if(changed)render(c);
        if(completed)await refresh();
      }
    }catch(error){if(current(w,id,g))note(c,error.message||String(error),true);}
    finally{c.checking=false;}
  }
  function detach(){
    ++generation;++readTicket;++detailTicket;events?.abort();events=null;
    root=null;workspace='';comparisonId='';
  }
  async function mount(container,selection){
    if(!validId(selection?.comparisonId)||typeof selection?.workspace!=='string'||!selection.workspace)
      throw Error('Open an original saved comparison before preparing its recipient package.');
    if(root===container&&workspace===selection.workspace&&comparisonId===selection.comparisonId){
      await refresh();return update();
    }
    detach();root=container;workspace=selection.workspace;comparisonId=selection.comparisonId;
    const w=workspace,id=comparisonId,g=generation,c=context(w,id);
    events=new AbortController();render(c);
    root.addEventListener('change',event=>{
      if(!current(w,id,g)||!event.target.matches?.('[data-lch-report]'))return;
      c.reportId=event.target.value;++c.selectionRevision;++detailTicket;persist(w,id,c);render(c);
    },{signal:events.signal});
    root.addEventListener('click',event=>{
      const target=event.target.closest?.('[data-lch-create],[data-lch-refresh],[data-lch-open]');
      if(!target||!root?.contains(target)||!current(w,id,g))return;
      event.preventDefault();
      Promise.resolve().then(()=>{
        if(!current(w,id,g))return;
        if(target.hasAttribute('data-lch-create'))return create();
        if(target.hasAttribute('data-lch-refresh'))return refresh().then(()=>update());
        return openPackage(target.getAttribute('data-lch-open'));
      }).catch(error=>{if(current(w,id,g))note(c,error.message||String(error),true);});
    },{signal:events.signal});
    await refresh();
    if(current(w,id,g))await update();
  }
  return {mount,update,detach};
}

/** Portable, source-bound requests shared by the offline report and native desk. */
export function createObservedLandcoverSelectionContract(){
  const REQUEST="upstate.observed-landcover-selection-request/v1",REPORT="upstate.observed-landcover-selection/v1";
  const normalized=new WeakSet();
  const HASH=/^[a-f0-9]{64}$/, groups=["water","snow_ice","developed","barren","forest","shrub","grass","agriculture","wetland"];
  const quantities=["gross_gain_ha","gross_loss_ha","net_ha"];
  const object=(value,label)=>{if(!value||typeof value!=="object"||Array.isArray(value))throw Error("Invalid "+label);return value;};
  const hash=(value,label)=>{if(typeof value!=="string"||!HASH.test(value))throw Error("Invalid "+label);return value;};
  function raster(value,label){
    object(value,label);if(!Number.isSafeInteger(value.year))throw Error("Invalid "+label+" year");
    return {year:value.year,sha256:hash(value.sha256,label+" raster identity")};
  }
  function binding(value,{native=false}={}){
    object(value,"source binding");
    const out={source_domain_sha256:hash(value.source_domain_sha256,"original polygon identity"),
      rasters:{before:raster(value.rasters?.before,"earlier"),after:raster(value.rasters?.after,"later")}};
    if(out.rasters.before.year>=out.rasters.after.year)throw Error("The original source years are out of order");
    if(value.analysis_manifest_sha256!==undefined)out.analysis_manifest_sha256=hash(value.analysis_manifest_sha256,"original manifest identity");
    if(!native&&out.analysis_manifest_sha256===undefined)throw Error("Keep the original analysis manifest identity");
    return out;
  }
  function selection(value,title){
    object(value,"watershed selection");
    const id=value.analysis_source_id;
    if(typeof id!=="string"||!id||id.length>256)throw Error("Choose the original analysis-run source");
    const ids=value.huc12s;
    if(!Array.isArray(ids)||!ids.length||ids.length>217||ids.some(id=>typeof id!=="string"||!/^\d{12}$/.test(id))||new Set(ids).size!==ids.length)
      throw Error("Choose distinct original twelve-character HUC12 identifiers");
    title=title??value.title;
    if(typeof title!=="string"||!title.trim()||title.trim().length>240)throw Error("Enter a comparison title of 1–240 characters");
    return {analysis_source_id:id,analysis_sha256:hash(value.analysis_sha256,"original analysis identity"),title:title.trim(),huc12s:[...ids]};
  }
  function view(value={}){
    object(value,"display hints");const group=value.group??"developed",group_metric=value.group_metric??"net_ha";
    if(!groups.includes(group)||!quantities.includes(group_metric))throw Error("Unknown comparison display hints");
    return {group,group_metric};
  }
  function parse(value){
    object(value,"saved comparison");
    if(value.schema===REPORT){
      const chosen=selection(value.selection,value.title),original=binding(value.binding,{native:true});
      if(value.binding.analysis_source_id!==chosen.analysis_source_id||value.binding.analysis_sha256!==chosen.analysis_sha256)
        throw Error("The native saved selection differs from its source binding");
      const parsed={schema:REQUEST,selection:chosen,binding:original,view:view(),source_format:"native_saved_comparison"};normalized.add(parsed);return parsed;
    }
    if(value.schema!==REQUEST||Object.keys(value).some(k=>!["schema","selection","binding","view"].includes(k)))
      throw Error("Choose a saved observed land-cover selection or portable request");
    const chosen=selection(value.selection),original=binding(value.binding);
    if(Object.keys(value.selection).some(k=>!["analysis_source_id","analysis_sha256","title","huc12s"].includes(k)))
      throw Error("Portable requests resolve collection IDs in the current Workspace");
    if(Object.keys(value.binding).some(k=>!["analysis_manifest_sha256","source_domain_sha256","rasters"].includes(k)))
      throw Error("Portable requests need the original source binding only");
    const parsed={schema:REQUEST,selection:chosen,binding:original,view:view(value.view),source_format:"portable_request"};normalized.add(parsed);return parsed;
  }
  function make(value){
    const p=parse({...value,schema:REQUEST});
    return {schema:REQUEST,selection:p.selection,binding:p.binding,view:p.view};
  }
  function assertBinding(request,actual,{requireManifest=false}={}){
    const p=normalized.has(request)?request:parse(request),expected=p.binding;
    object(actual,"current original binding");
    if(actual.analysis_source_id!==p.selection.analysis_source_id||actual.analysis_sha256!==p.selection.analysis_sha256||
       actual.source_domain_sha256!==expected.source_domain_sha256)
      throw Error("The selected analysis or original polygon edition differs");
    const got=binding(actual,{native:true});
    for(const side of ["before","after"])if(got.rasters[side].year!==expected.rasters[side].year||got.rasters[side].sha256!==expected.rasters[side].sha256)
      throw Error("The selected original raster years or identities differ");
    if(requireManifest&&p.source_format!=="native_saved_comparison"&&actual.analysis_manifest_sha256!==expected.analysis_manifest_sha256)
      throw Error("The original analysis manifest edition differs");
    return p;
  }
  function resolve(request,sources,preferredChoice=null){
    const p=normalized.has(request)?request:parse(request);
    let matches=(Array.isArray(sources)?sources:[]).filter(s=>s.analysis_source_id===p.selection.analysis_source_id&&s.analysis_sha256===p.selection.analysis_sha256);
    if(matches.length>1&&preferredChoice){const chosen=matches.filter(s=>s.source_collection_id===preferredChoice.source_collection_id&&s.analysis_source_id===preferredChoice.analysis_source_id&&s.analysis_sha256===preferredChoice.analysis_sha256);if(chosen.length===1)matches=chosen;}
    if(matches.length!==1)throw Error(matches.length?"Several retained sources match this analysis. Keep the current draft and choose one original source explicitly.":"Import the completed original analysis into this Workspace before opening this selection.");
    if(!HASH.test(matches[0].source_collection_id))throw Error("The retained source has no original Workspace collection identity");
    return {...matches[0]};
  }
  return {schema:REQUEST,parse,make,assertBinding,resolve};
}

